package android.graphics;import java.awt.*;import java.awt.geom.*;import java.util.*;public class Canvas {public Graphics2D g;private Stack<Graphics2D> stack=new Stack<>();public Canvas(Graphics2D g){this.g=g;g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_OFF);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);}public void drawRect(float l,float t,float r,float b,Paint p){g.setColor(p.color);g.fill(new Rectangle2D.Float(l,t,r-l,b-t));}public void drawText(String s,float x,float y,Paint p){g.setColor(p.color);g.setFont(Paint.font.deriveFont(p.size));g.drawString(s,x,y);}public void drawLine(float a,float b,float c,float d,Paint p){g.setColor(p.color);g.setStroke(new BasicStroke(p.stroke));g.draw(new Line2D.Float(a,b,c,d));}public void drawBitmap(Bitmap b,Object ignored,RectF dest,Paint p){g.drawImage(b.image,(int)dest.left,(int)dest.top,(int)dest.width(),(int)dest.height(),null);}public void scale(float x,float y){g.scale(x,y);}public void translate(float x,float y){g.translate(x,y);}public void save(){stack.push(g);g=(Graphics2D)g.create();}public void restore(){g.dispose();g=stack.pop();}public void clipRect(float l,float t,float r,float b){g.clip(new Rectangle2D.Float(l,t,r-l,b-t));}public void clipRect(RectF r){g.clip(new Rectangle2D.Float(r.left,r.top,r.width(),r.height()));}}